create table if not exists identity.user_preferences ( id uuid primary key default gen_random_uuid(), user_id uuid not null references identity.profiles (id) on delete cascade unique, language text default 'ar' check (language in ('ar', 'en')), theme text default 'system' check (theme in ('light', 'dark', 'system')), prayer_method text default 'mwl' check (prayer_method in ('mwl', 'egyptian', 'karachi', 'umm_al_qura', 'dubai', 'qatar', 'kuwait', 'tehran', 'jafari', 'custom')), asr_method text default 'standard' check (asr_method in ('standard', 'hanafi')), fajr_angle numeric(4,1) default 18.0, isha_angle numeric(4,1) default 17.0, latitude numeric(9,6), longitude numeric(9,6), timezone text default 'UTC', hijri_adjustment smallint default 0, created_at timestamptz default now(), updated_at timestamptz default now() );
